// Dragon: glides on its soaring pose while flying across the field; beats its wings (idle pose) while hovering or fighting
const so=!!(f.T.soar&&!f.dead&&!over&&f.walking&&f.lunge<0&&f.baseAlt>(ALT+LOW_ALT)/2&&!(f.stun>0));
if(f.T.soar&&so!==!!f.soaring){ f.soaring=so; e.classList.toggle('soar',so); }
fr=f.dead?(f.frame||0):Math.floor(((clock+f.phase)/(so?f.T.soar.period:f.T.flap))*16)%16
